import { unzipSync } from "fflate";
// Generates the Farmer's Delight sprite registry + CSS from one pinned upstream
// commit. Run:
//   pnpm --filter @tennantite/textures sync:farmersdelight-sprites
//
// The commit is pinned so the generated files are reproducible. `--check`
// re-renders and compares against the committed files.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const FD_COMMIT = "dd8b9b0bfec916a2da88a6d64e3a37f4a02c3259";
const FD_ZIP = `https://codeload.github.com/vectorwing/FarmersDelight/zip/${FD_COMMIT}`;
const FD_ASSET_ROOT = "src/main/resources/assets/farmersdelight/textures/gui/";

const ROOT = fileURLToPath(new URL("../", import.meta.url));
const OUT_TS = `${ROOT}src/farmersdelight-sprites.generated.ts`;
const OUT_CSS = `${ROOT}css/farmersdelight-sprites.generated.css`;
const OUT_TEXTURES = `${ROOT}css/farmersdelight-textures.css`;

const check = process.argv.includes("--check");

const SOURCES = [
  { file: "cooking_pot.png", name: "cooking_pot" },
  { file: "fd_icons.png", name: "fd_icons" },
];

function cssVar(name) {
  return `--mc-fd-${name.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`;
}

async function download(url) {
  let lastError;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} ${response.statusText}`);
      }
      return new Uint8Array(await response.arrayBuffer());
    }
    catch (error) {
      lastError = error;
      if (attempt < 4) {
        await new Promise(resolve => setTimeout(resolve, attempt * 500));
      }
    }
  }
  throw new Error(`cannot download ${url}`, { cause: lastError });
}

function pngSize(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset);
  return { height: view.getUint32(20), width: view.getUint32(16) };
}

function sourceName(fullName, assetRoot, file) {
  const marker = fullName.indexOf(assetRoot);
  return marker !== -1 && (fullName.slice(marker + assetRoot.length) === file);
}

const zip = await download(FD_ZIP);
const files = unzipSync(zip, {
  filter: file => file.name.endsWith(".png") && file.name.includes(FD_ASSET_ROOT),
});

const entries = SOURCES.map(({ file, name }) => {
  const match = Object.entries(files).find(([fullName]) => sourceName(fullName, FD_ASSET_ROOT, file));
  if (!match) {
    throw new Error(`missing ${file} under ${FD_ASSET_ROOT}`);
  }
  const bytes = match[1];
  const { height, width } = pngSize(bytes);
  return {
    base64: Buffer.from(bytes).toString("base64"),
    cssVar: cssVar(name),
    height,
    name,
    sha256: createHash("sha256").update(bytes).digest("hex"),
    width,
  };
});

if (entries.length !== 2) {
  throw new Error(`expected 2 Farmer's Delight sprites, got ${entries.length}`);
}

const metaLines = entries.map(entry => `  ${JSON.stringify(entry.name)}: {
    cssVar: ${JSON.stringify(entry.cssVar)},
    height: ${entry.height},
    sha256: ${JSON.stringify(entry.sha256)},
    width: ${entry.width},
  },`);

const ts = `// Generated by scripts/sync-farmersdelight-sprites.mjs — DO NOT EDIT.
// Source: Farmer's Delight ${FD_COMMIT} (MIT).
// See LICENSE-ASSETS.md.
// Regenerate: pnpm --filter @tennantite/textures sync:farmersdelight-sprites

export interface FarmersDelightSpriteMeta {
  cssVar: string;
  height: number;
  sha256: string;
  width: number;
}

export const farmersDelightSpriteMeta = {
${metaLines.join("\n")}
} as const;

export type FarmersDelightSpriteName = keyof typeof farmersDelightSpriteMeta;
`;

const cssLines = entries.map(
  entry => `  ${entry.cssVar}: url("data:image/png;base64,${entry.base64}");`,
);

const css = `/*
 * Generated by scripts/sync-farmersdelight-sprites.mjs — DO NOT EDIT.
 * Source: Farmer's Delight ${FD_COMMIT} (MIT).
 * See LICENSE-ASSETS.md.
 */
:root {
${cssLines.join("\n")}
}
`;

const textures = `/*
 * Farmer's Delight sprite layer. Import after the vanilla sprite CSS.
 * Generated data URIs live in farmersdelight-sprites.generated.css.
 */
@import "./farmersdelight-sprites.generated.css";

.mc-fd-sprite {
  background-repeat: no-repeat;
  image-rendering: pixelated;
}
`;

if (check) {
  let isStale = false;
  for (const [file, expected] of [
    [OUT_TS, ts],
    [OUT_CSS, css],
    [OUT_TEXTURES, textures],
  ]) {
    let actual = "";
    try {
      actual = readFileSync(file, "utf8");
    }
    catch {
      isStale = true;
      continue;
    }
    if (actual === expected) {
      continue;
    }
    isStale = true;
    console.error(`out of date: ${file}`);
  }
  if (isStale) {
    process.exit(1);
  }
  console.log(`Farmer's Delight sprites up to date (${entries.length})`);
}
else {
  writeFileSync(OUT_TS, ts);
  writeFileSync(OUT_CSS, css);
  writeFileSync(OUT_TEXTURES, textures);
  console.log(`wrote ${entries.length} Farmer's Delight sprites`);
}
